import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String text = scanner.nextLine();
        if (text.length() > 0) {
            text = text.charAt(0) + text.substring(1).replaceFirst("at", "@");
            if (text.length() > 1) {
                System.out.println(text.charAt(0) + text.substring(1, text.length() - 1).replace("dot", ".") + text.charAt(text.length() - 1));
            } else {
                System.out.println(text);
            }
        } else {
            System.out.println(text);
        }
        scanner.close();
    }
}
